Object.entries(AGENT_TEAM_I18N_20260722).forEach(([code, patch]) => {
  const registry = I18N.reg[code];
  if (!registry) return;
  registry.nav = registry.nav || {};
  registry.nav.labels = registry.nav.labels || {};
  registry.nav.labels['Agent Team'] = patch.label;
  registry.meta = registry.meta || {};
  registry.meta['team-mode'] = { title: patch.label, sub: patch.sub };
  registry.meta['technical-demos'] = Object.assign(
    {},
    registry.meta['technical-demos'] || {},
    { sub: patch.demosSub },
  );
  registry.tr = registry.tr || {};
  Object.assign(registry.tr, patch.tr);
});

